                        done  <= 1'b1;
                        state <= IDLE;
                    end else begin
                        state <= WAIT_STOP;
                    end
                end

                WAIT_STOP: begin
                    if (in)
                        state <= IDLE;
                end

                default: begin
                    state     <= IDLE;
